      )
      return [
        {
          id: row.id,
          name: row.name,
          integration: integration.name,
          searchable: Boolean(integration.search),
          settings: Object.fromEntries(
            Object.entries(row.settings).filter(([k]) => !hidden.has(k)),
          ),
        },
      ]
    })
  },
